BEGIN;CREATE TABLE IF NOT EXISTS workforce_teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS workforce_team_members(team_id uuid NOT NULL REFERENCES workforce_teams(id) ON DELETE CASCADE,professional_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(team_id,professional_id));ALTER TABLE workforce_teams ENABLE ROW LEVEL SECURITY;ALTER TABLE workforce_teams FORCE ROW LEVEL SECURITY;ALTER TABLE workforce_team_members ENABLE ROW LEVEL SECURITY;ALTER TABLE workforce_team_members FORCE ROW LEVEL SECURITY;CREATE POLICY workforce_teams_tenant_isolation ON workforce_teams USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);CREATE POLICY workforce_team_members_tenant_isolation ON workforce_team_members USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON workforce_teams,workforce_team_members TO app_runtime;COMMIT;
